package com.travelneveralone.tna

import java.util.Locale

// Port of TNAiOS Core/Services/PhoneCountry.swift + PhoneInput.swift: as-you-type
// phone rules behind the login field. Pure JVM (no Android), covered by tests.
// The field holds only the NATIONAL part; the calling code lives in the chip.
// Table: PhoneCountryData.kt, generated by TNAiOS/Scripts/gen-phone-countries.cjs.

data class PhoneCountry(
    /** ISO 3166-1 alpha-2, e.g. "RU". */
    val iso: String,
    /** Calling code without '+', e.g. "7". */
    val dialCode: String,
    /** National mobile mask, '#' = one digit, e.g. "### ###-##-##". */
    val mask: String,
    /** Allowed national mobile number lengths. */
    val lengths: IntRange,
    /** Example national mobile number, for the placeholder. */
    val example: String,
    /** Trunk prefix typed out of habit ("8" RU, "0" NL); empty if ambiguous. */
    val trunkPrefix: String,
    /** Picked by default for a shared code (+7 → RU, +1 → US). */
    val isMainForCode: Boolean,
    /** Regex for the start of a national number of a non-main country on a shared code (KZ: "7"). */
    val leadingDigits: String,
) {
    /** Russian name; the ISO code for territories the platform can't name. */
    val name: String get() = RU_NAMES[iso] ?: iso

    /** Emoji flag from regional indicator symbols. */
    val flag: String
        get() = buildString { iso.uppercase().forEach { appendCodePoint(0x1F1E6 + (it - 'A')) } }

    val dialCodeDisplay: String get() = "+$dialCode"

    /** How many digits the mask lays out (the typical length). */
    val maskLength: Int get() = mask.count { it == '#' }

    /** Placeholder in the local format, e.g. "912 345-67-89". */
    val placeholder: String get() = PhoneInput.format(example, mask)

    companion object {
        val byIso: Map<String, PhoneCountry> by lazy { PHONE_COUNTRIES.associateBy { it.iso } }

        fun withIso(iso: String): PhoneCountry? = byIso[iso.uppercase()]

        /** Fallback when nothing else is known: most travellers have Russian numbers. */
        val russia: PhoneCountry get() = byIso.getValue("RU")

        /** The country to preselect for a device region, else Russia. */
        fun preferred(region: String?): PhoneCountry =
            region?.takeIf { it.isNotBlank() }?.let(::withIso) ?: russia

        /** Shown above the full list: post-Soviet space first, then where travellers live and go. */
        val POPULAR_ISO = listOf("RU", "KZ", "BY", "UZ", "KG", "AM", "GE", "AZ",
                                 "TR", "AE", "TH", "RS", "ME", "CY", "IL", "DE")

        /** Popular countries, the device's own on top if it isn't one of them. */
        fun popular(region: String?): List<PhoneCountry> {
            val list = POPULAR_ISO.mapNotNull { byIso[it] }.toMutableList()
            val local = region?.let(::withIso)
            if (local != null && local !in list) list.add(0, local)
            return list
        }

        /** All countries, alphabetically by Russian name. */
        val sortedByName: List<PhoneCountry> by lazy {
            val collator = java.text.Collator.getInstance(Locale("ru"))
            PHONE_COUNTRIES.sortedWith { a, b -> collator.compare(a.name, b.name) }
        }

        /** Search by Russian or English name, ISO code or calling code ("+31", "31"). */
        fun search(query: String): List<PhoneCountry> {
            val q = query.trim()
            if (q.isEmpty()) return sortedByName
            val digits = q.filter { it in '0'..'9' }
            if (digits.isNotEmpty() && digits.length == q.count { it != '+' && it != ' ' }) {
                // Pure code query: exact code first, then longer codes with that prefix.
                return sortedByName
                    .filter { it.dialCode.startsWith(digits) }
                    .sortedWith(compareBy({ if (it.dialCode == digits) 0 else 1 }, { it.dialCode.length }))
            }
            return sortedByName.filter {
                it.name.contains(q, ignoreCase = true) ||
                    (EN_NAMES[it.iso]?.contains(q, ignoreCase = true) ?: false) ||
                    it.iso.equals(q, ignoreCase = true)
            }
        }

        private val RU_NAMES: Map<String, String> by lazy { names(Locale("ru")) }
        private val EN_NAMES: Map<String, String> by lazy { names(Locale.ENGLISH) }

        private fun names(locale: Locale): Map<String, String> =
            PHONE_COUNTRIES.associate { c ->
                val n = Locale("", c.iso).getDisplayCountry(locale)
                // Unknown regions come back as the code itself.
                c.iso to (if (n.isBlank() || n == c.iso) c.iso else n)
            }
    }
}

object PhoneInput {

    /** Result of feeding the field's raw text through the rules. */
    data class Edit(
        val country: PhoneCountry,
        /** National number, digits only, clamped to the country's max length. */
        val national: String,
        /** Digits after '+' while a calling code is still being typed ("+3"), else null. */
        val pendingCode: String?,
        /** Digits dropped from the front (calling code, trunk prefix), for caret math. */
        val droppedLeading: Int,
    ) {
        val display: String get() = pendingCode?.let { "+$it" } ?: format(national, country.mask)
    }

    private fun digitsOf(s: String) = s.filter { it in '0'..'9' }

    /** Lays digits over a mask: separators only between digits, extra digits stick to the last group. */
    fun format(digits: String, mask: String): String {
        val out = StringBuilder()
        val separators = StringBuilder()
        var i = 0
        for (symbol in mask) {
            if (i >= digits.length) break
            if (symbol == '#') {
                out.append(separators); separators.clear()
                out.append(digits[i++])
            } else {
                separators.append(symbol)
            }
        }
        out.append(digits, i, digits.length)
        return out.toString()
    }

    fun isComplete(national: String, country: PhoneCountry): Boolean = national.length in country.lengths

    /** "+79161234567", or "" when there is no number yet. */
    fun e164(national: String, country: PhoneCountry): String =
        if (national.isEmpty()) "" else "+${country.dialCode}$national"

    /** Digits only, cut to the country's max length (used when the country changes). */
    fun clamp(national: String, country: PhoneCountry): String = digitsOf(national).take(country.lengths.last)

    private val byDialCode: Map<String, List<PhoneCountry>> by lazy { PHONE_COUNTRIES.groupBy { it.dialCode } }

    /**
     * Splits international digits (no '+') into country + national number. Calling
     * codes are prefix-free, so the first match is the only one. [current] wins a
     * shared code (+1 US/CA) unless the number says otherwise.
     */
    fun resolve(digits: String, current: PhoneCountry?): Pair<PhoneCountry, String>? {
        if (digits.isEmpty()) return null
        for (length in 1..minOf(3, digits.length)) {
            val candidates = byDialCode[digits.take(length)] ?: continue
            val national = digits.drop(length)
            return pick(candidates, national, current) to national
        }
        return null
    }

    private fun pick(candidates: List<PhoneCountry>, national: String, current: PhoneCountry?): PhoneCountry {
        if (national.isNotEmpty()) {
            candidates.firstOrNull {
                it.leadingDigits.isNotEmpty() && Regex("^(?:${it.leadingDigits})").containsMatchIn(national)
            }?.let { return it }
        }
        // Keep the user's choice unless it is a "leading digits" country and the
        // number plainly belongs to the main one (KZ chosen, +7 916…).
        if (current != null && current in candidates && (national.isEmpty() || current.leadingDigits.isEmpty())) {
            return current
        }
        return candidates.firstOrNull { it.isMainForCode } ?: candidates.first()
    }

    /** Reads whatever is in the field now (typed, pasted, autofilled) against the selected country. */
    fun apply(text: String, country: PhoneCountry): Edit {
        val digits = digitsOf(text)
        var c = country
        var national = digits
        var dropped = 0

        if (text.trim().startsWith("+")) {
            // International: the code picks the country. Until it is complete the
            // field shows the raw "+3…" and nothing counts as a number.
            val resolved = resolve(digits, country)
                ?: return Edit(country, "", digits.take(3), 0)
            c = resolved.first
            national = resolved.second
            dropped = c.dialCode.length
        } else if (digits.length > c.lengths.last && digits.startsWith(c.dialCode) &&
            (digits.length - c.dialCode.length) in c.lengths
        ) {
            // Full number without '+' ("79161234567" with Russia selected).
            national = digits.drop(c.dialCode.length)
            dropped = c.dialCode.length
        }

        // Trunk prefix out of habit: "8 916…", "06…". A lone "8" stays on screen so
        // the keystroke isn't swallowed; it goes once the next digit arrives.
        val trunk = c.trunkPrefix
        if (trunk.isNotEmpty() && national.length > trunk.length && national.startsWith(trunk)) {
            national = national.drop(trunk.length)
            dropped += trunk.length
        }
        return Edit(c, national.take(c.lengths.last), null, dropped)
    }

    /**
     * Turns a text-field change into raw text + digits before the caret. Backspace
     * on a separator deletes the digit before it (otherwise the reformat would put
     * the separator back and the key would seem dead).
     */
    fun replace(old: String, new: String, newCaret: Int): Pair<String, Int> {
        var text = new
        var caret = newCaret.coerceIn(0, new.length)
        if (new.length == old.length - 1 && digitsOf(new) == digitsOf(old)) {
            val index = text.substring(0, caret).indexOfLast { it in '0'..'9' }
            if (index >= 0) {
                text = text.removeRange(index, caret)
                caret = index
            }
        }
        return text to text.substring(0, caret).count { it in '0'..'9' }
    }

    /** Caret offset in [display] right after its [count]-th digit. */
    fun caretOffset(count: Int, display: String): Int {
        if (count <= 0) return 0
        var seen = 0
        display.forEachIndexed { offset, ch ->
            if (ch in '0'..'9' && ++seen == count) return offset + 1
        }
        return display.length
    }

    /**
     * Best reading of a stored or free-typed phone (booking form, beta logins).
     * "+…" is international. Otherwise, in order: a typical-length local number in
     * [fallback] ("06 12345678" for NL), international digits without '+'
     * ("31612345678"), the legacy Russian rules ("8 916…", "916…").
     */
    fun parse(raw: String, fallback: PhoneCountry): Pair<PhoneCountry, String> {
        val digits = digitsOf(raw)
        if (digits.isEmpty()) return fallback to ""
        if (raw.contains('+')) {
            val edit = apply("+$digits", fallback)
            return if (edit.pendingCode == null) edit.country to edit.national else fallback to ""
        }
        val local = apply(digits, fallback)
        val nothingCut = local.national.length + local.droppedLeading == digits.length
        if (nothingCut && isComplete(local.national, local.country) && local.national.length <= local.country.maskLength) {
            return local.country to local.national
        }
        for (candidate in listOf(digits, PhoneNumber.digits(digits))) {
            val found = resolve(candidate, fallback)
            if (found != null && isComplete(found.second, found.first)) return found
        }
        return local.country to local.national
    }
}
